    """Move every non-background cell down one row, preserving the grid size."""
    if not grid:
        return []
    background = max(set(value for row in grid for value in row), key=lambda value: sum(r.count(value) for r in grid))
    height, width = len(grid), len(grid[0])
    out = [[background for _ in range(width)] for _ in range(height)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != background and r + 1 < height:
